  "answers": {
    "skill": {
      "type": "choice",
      "choice": "follow",
      "probabilities": { "follow": 0.97, "chat": 0.03, "navigate_to": 0, "pick": 0, "place": 0, "unclear": 0 },
      "confidence": 0.95
    },
    "need_confirm": { "type": "noul", "noul": 0.58 }
  },
  "usage": { "input_tokens": 627, "output_tokens": 79, "cost": 0.0000263 }
}
```

