import json,sys
try:
  c=json.load(sys.stdin)
except Exception as e:
  print('  ERR', e); raise SystemExit
keep={k:c[k] for k in ('model_type','architectures','is_decoder','is_encoder_decoder','use_cache','sliding_window','max_position_embeddings','hidden_size') if k in c}
print('  ',keep)
print('   pooling:', c.get('pooling_type') or c.get('sentence_pooling_method') or c.get('pooling') or '-')
"; done

